use narrator_studio::downloads::{transfer_file,TransferControl,ModelFile,Integrity};
use std::{sync::{Arc,Mutex},io::{Read,Write},net::TcpListener};
fn file()->ModelFile{ModelFile{relative_path:"config.json".into(),bytes:Some(5),integrity:Integrity::Sha256("2cf24dba5fb0a30e26e83b2ac5b9e29e1b161e5c1fa7425e73043362938b9824".into())}}
fn server(body:&'static [u8],status:&'static str)->String{let socket=TcpListener::bind("127.0.0.1:0").unwrap();let address=socket.local_addr().unwrap();std::thread::spawn(move||{let(mut stream,_)=socket.accept().unwrap();let mut request=[0u8;4096];let _=stream.read(&mut request);write!(stream,"HTTP/1.1 {status}\r\nContent-Length: {}\r\nConnection: close\r\n\r\n",body.len()).unwrap();stream.write_all(body).unwrap();});format!("http://{address}/file")}
#[tokio::test]async fn progress_uses_received_bytes_and_verifies(){let dir=tempfile::tempdir().unwrap();let seen=Arc::new(Mutex::new(Vec::new()));let copy=seen.clone();transfer_file(&reqwest::Client::new(),&server(b"hello","200 OK"),dir.path(),&file(),"revision",&TransferControl::default(),Arc::new(move|n|copy.lock().unwrap().push(n))).await.unwrap();assert_eq!(std::fs::read(dir.path().join("config.json")).unwrap(),b"hello");assert_eq!(seen.lock().unwrap().last(),Some(&5));}
#[tokio::test]async fn checksum_failure_never_marks_ready(){let dir=tempfile::tempdir().unwrap();assert!(transfer_file(&reqwest::Client::new(),&server(b"wrong","200 OK"),dir.path(),&file(),"revision",&TransferControl::default(),Arc::new(|_|{})).await.is_err());assert!(!dir.path().join("config.json").exists());}
#[tokio::test]async fn range_ignored_restarts_without_append(){let dir=tempfile::tempdir().unwrap();std::fs::write(dir.path().join("config.json.part"),b"he").unwrap();std::fs::write(dir.path().join("config.json.part.json"),r#"{"revision":"revision"}"#).unwrap();transfer_file(&reqwest::Client::new(),&server(b"hello","200 OK"),dir.path(),&file(),"revision",&TransferControl::default(),Arc::new(|_|{})).await.unwrap();assert_eq!(std::fs::read(dir.path().join("config.json")).unwrap(),b"hello");}
#[tokio::test]async fn cancel_preserves_partial(){let dir=tempfile::tempdir().unwrap();let control=TransferControl::default();control.pause();assert_eq!(transfer_file(&reqwest::Client::new(),"http://127.0.0.1:1",dir.path(),&file(),"revision",&control,Arc::new(|_|{})).await.unwrap_err(),"paused");}
